export function allowedActions(o) {
 if(o.round>=12||o.health<=0)return [];
 const high=['swarm','brute'],cost={scout:1,swarm:2,brute:3};
 return ['rest',...Object.keys(cost).filter(k=>o.health>3&&cost[k]<=o.budget&&(k!=='swarm'||o.health>=6)&&(k!=='brute'||o.health>=8)&&(!high.includes(k)||!high.includes(o.lastKind)))];
}
